ALTER TABLE chat_messages ADD COLUMN IF NOT EXISTS seq BIGINT UNSIGNED NOT NULL AUTO_INCREMENT UNIQUE;
ALTER TABLE chat_reads ADD COLUMN IF NOT EXISTS last_seq BIGINT UNSIGNED NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS payment_setups (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, consumed BOOLEAN NOT NULL DEFAULT FALSE, expires_at DATETIME(3) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id));
